namespace sv_7381e6f0e95142d4840f4a8564839c6a.Services;

public class WarehouseInfo
{
    public required string Id { get; init; }
    public required string Name { get; init; }
}

/// <summary>
/// Scoped service that tracks the currently selected warehouse for a single user circuit.
/// Components subscribe to <see cref="OnChange"/> to react when the selection changes.
/// </summary>
public class WarehouseState
{
    private static readonly List<WarehouseInfo> _allWarehouses =
    [
        new() { Id = "wh-1", Name = "Warehouse A" },
        new() { Id = "wh-2", Name = "Warehouse B" },
        new() { Id = "wh-3", Name = "Warehouse C" },
    ];

    public IReadOnlyList<WarehouseInfo> Warehouses => _allWarehouses;

    public WarehouseInfo Current { get; private set; } = _allWarehouses[0];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        var warehouse = _allWarehouses.FirstOrDefault(w => w.Id == warehouseId);
        if (warehouse is not null && warehouse.Id != Current.Id)
        {
            Current = warehouse;
            OnChange?.Invoke();
        }
    }
}

namespace sv_7381e6f0e95142d4840f4a8564839c6a.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all subscribers
/// when new data arrives. Polling is driven by the consumer; when fresh data is fetched,
/// <see cref="OnAlertCountChanged"/> fires so every subscribed component updates.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LatestAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// After fetching, notifies all subscribers so every component sees the new value.
    /// </summary>
    public async Task<int> GetLowStockCountAsync(string warehouseId)
    {
        await Task.Delay(50); // simulate async DB call
        LatestAlertCount = _random.Next(0, 16);
        OnAlertCountChanged?.Invoke();
        return LatestAlertCount;
    }
}

