@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center gap-2">
    <label for="warehouse-select" class="text-nowrap fw-semibold mb-0">Warehouse:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            value="@WarehouseState.Current.Id"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= _handler;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

@if (AlertService.LatestAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@AlertService.LatestAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-auto">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Subscribe so this badge updates whenever ANY component fetches new alert data.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _handler;
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard – @WarehouseState.Current.Name</PageTitle>

<h1>Dashboard</h1>
<p class="lead">Viewing: <strong>@WarehouseState.Current.Name</strong></p>

<div class="row mb-4">
    <div class="col-md-4">
        <div class="card @(alertCount > 5 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(alertCount > 5 ? "text-danger" : "text-success")">
                    @alertCount
                </p>
                <p class="text-muted">items below minimum level</p>
            </div>
        </div>
    </div>
</div>

<p class="text-muted">
    <small>Polling every 10 seconds &bull; Last updated: @lastUpdated.ToString("HH:mm:ss")</small>
</p>

@code {
    private int alertCount;
    private DateTime lastUpdated = DateTime.Now;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override async Task OnInitializedAsync()
    {
        // React when another component changes the warehouse.
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // React when alert data is refreshed (keeps this component in sync
        // even if another subscriber triggered the fetch).
        _alertHandler = () => InvokeAsync(() =>
        {
            alertCount = AlertService.LatestAlertCount;
            lastUpdated = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertCountChanged += _alertHandler;

        await FetchAlerts();
        StartPolling();
    }

    private async Task OnWarehouseChanged()
    {
        // Warehouse changed — fetch immediately and restart the polling interval.
        StopPolling();
        await FetchAlerts();
        StartPolling();
        StateHasChanged();
    }

    private async Task FetchAlerts()
    {
        alertCount = await AlertService.GetLowStockCountAsync(WarehouseState.Current.Id);
        lastUpdated = DateTime.Now;
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await InvokeAsync(async () =>
                {
                    await FetchAlerts();
                    StateHasChanged();
                });
            }
        }
        catch (OperationCanceledException) { }
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

