toolArgs.new_str:
using sv_7381e6f0e95142d4840f4a8564839c6a.Components;
using sv_7381e6f0e95142d4840f4a8564839c6a.Services;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents();

// Scoped = per-circuit on InteractiveServer, so each user gets independent state.
builder.Services.AddScoped<WarehouseState>();
builder.Services.AddScoped<InventoryAlertService>();

